import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports a thrown string with its cause and preserves the caller rejection [specs/hal-engine-config-hooks/spec.md#9]', async () => {
  const session: ChatSession = {sessionId: 'session', userId: 'user', entries: []};
  const errors: Error[] = [];
  const order: string[] = [];
  const orchestrator = createChatOrchestrator(createMockProvider(), new PromptBuilder({identity: 'Assistant'}), undefined, {
    hooks: {
      beforeModelResponse: () => Promise.reject('prompt unavailable'),
      onError: (_session, error) => {
        errors.push(error);
        order.push('onError');
        return Promise.resolve();
      },
      afterSession: () => {
        order.push('afterSession');
        return Promise.resolve();
      },
    },
  });

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({errors, message: errors[0]?.message, cause: errors[0]?.cause, order, rejection}).toEqual({
    errors: [expect.any(Error)],
    message: 'prompt unavailable',
    cause: 'prompt unavailable',
    order: ['onError', 'afterSession'],
    rejection: 'prompt unavailable',
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/onErrorCause.test.ts"

